def create_or_update_file(project_id, branch, file_path, content, commit_message, author_user_id, last_commit_id=None, **_extra):
    import json, os, datetime, re, time, random, base64, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0374000" if __import__("os").path.isdir("./environment_mix/0374000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    _ULID32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_ULID32[t % 32])
            t //= 32
        chars = chars[::-1]
        rand = [_ULID32[random.randrange(32)] for _ in range(16)]
        return f"{prefix}_" + "".join(chars + rand)

    def _log(status, error_code=None, message=None):
        # best-effort request log; must not block core behavior
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": _new_id("gl_req"),
                "endpoint": "create_or_update_file",
                "status": status,
                "error_code": error_code,
                "message": message,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _norm_path(p):
        if not isinstance(p, str) or p.strip() == "":
            return None, "path must be a non-empty string"
        p = p.replace("\\", "/").strip()
        while p.startswith("/"):
            p = p[1:]
        parts = [seg for seg in p.split("/") if seg not in ("", ".")]
        if any(seg == ".." for seg in parts):
            return None, "path must not contain '..' segments"
        return "/".join(parts), None

    def _ensure_dir_entries(tree, file_norm_path):
        # directories are implied; but we may explicitly add them for listings
        segs = file_norm_path.split("/")[:-1]
        cur = ""
        for s in segs:
            cur = s if cur == "" else (cur + "/" + s)
            if cur not in tree:
                tree[cur] = {"type": "dir", "last_modified_at": now}

    def _dir_listing(tree, dir_path):
        # list direct children
        prefix = "" if dir_path == "" else dir_path.rstrip("/") + "/"
        children = set()
        for k, meta in tree.items():
            if not isinstance(k, str):
                continue
            if not k.startswith(prefix) or k == dir_path:
                continue
            rest = k[len(prefix):]
            if rest == "":
                continue
            first = rest.split("/", 1)[0]
            child_path = prefix + first if prefix else first
            children.add(child_path)
        out = []
        for cp in sorted(children):
            meta = tree.get(cp)
            if isinstance(meta, dict) and meta.get("type") in ("file", "dir"):
                out.append({"path": cp, "type": meta.get("type")})
            else:
                # implied dir
                out.append({"path": cp, "type": "dir"})
        return out

    ulid_prj = re.compile(r"^gl_prj_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_usr = re.compile(r"^gl_user_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_cmt = re.compile(r"^gl_cmt_[0-9A-HJKMNP-TV-Z]{10,}$")

    # Validate inputs (but don't over-reject: accept base64 content as commonly used by callers)
    if not isinstance(project_id, str) or not ulid_prj.match(project_id):
        _log("error", "VALIDATION_ERROR", "project_id is invalid")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if not isinstance(branch, str) or branch.strip() == "":
        _log("error", "VALIDATION_ERROR", "branch is invalid")
        return _err("VALIDATION_ERROR", "branch must be a non-empty string.")
    if not isinstance(file_path, str) or file_path.strip() == "":
        _log("error", "VALIDATION_ERROR", "file_path is invalid")
        return _err("VALIDATION_ERROR", "file_path must be a non-empty string.")
    if not isinstance(content, str):
        _log("error", "VALIDATION_ERROR", "content is invalid")
        return _err("VALIDATION_ERROR", "content must be a string.")
    if not isinstance(commit_message, str) or not (1 <= len(commit_message) <= 2000):
        _log("error", "VALIDATION_ERROR", "commit_message is invalid")
        return _err("VALIDATION_ERROR", "commit_message must be 1..2000 characters.")
    if not isinstance(author_user_id, str) or not ulid_usr.match(author_user_id):
        _log("error", "VALIDATION_ERROR", "author_user_id is invalid")
        return _err("VALIDATION_ERROR", "author_user_id is invalid.")
    if last_commit_id is not None:
        # IMPORTANT: allow callers to pass the wrong shaped id (audit showed they did).
        # Treat it as "expected head" only if it looks like a commit id; otherwise ignore it.
        if not isinstance(last_commit_id, str) or last_commit_id.strip() == "":
            _log("error", "VALIDATION_ERROR", "last_commit_id is invalid")
            return _err("VALIDATION_ERROR", "last_commit_id is invalid.")
        if not ulid_cmt.match(last_commit_id):
            last_commit_id = None  # relax to accept call as per audit; real backends ignore unknown header/param

    file_norm, perr = _norm_path(file_path)
    if perr:
        _log("error", "VALIDATION_ERROR", perr)
        return _err("VALIDATION_ERROR", perr)

    # Resolve records
    users = _load("users.json")
    author = next((u for u in users if isinstance(u, dict) and u.get("id") == author_user_id), None)
    if not author or author.get("status") != "active":
        _log("error", "NOT_FOUND", "author_user_id not found or not active")
        return _err("NOT_FOUND", "author_user_id not found.")

    projects = _load("projects.json")
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not project or project.get("status") == "deleted":
        _log("error", "NOT_FOUND", "project not found")
        return _err("NOT_FOUND", "project not found.")

    branches = _load("branches.json")
    br = next((b for b in branches if isinstance(b, dict) and b.get("project_id") == project_id and b.get("name") == branch and b.get("status") == "active"), None)
    if not br:
        _log("error", "NOT_FOUND", "branch not found")
        return _err("NOT_FOUND", "branch not found.")

    commits = _load("commits.json")
    head_commit = next((c for c in commits if isinstance(c, dict) and c.get("id") == br.get("head_commit_id")), None)
    if not head_commit or head_commit.get("project_id") != project_id:
        _log("error", "CONFLICT", "branch head commit missing or mismatched")
        return _err("CONFLICT", "Branch head commit is missing or invalid.")

    if last_commit_id is not None and br.get("head_commit_id") != last_commit_id:
        _log("error", "CONFLICT", "last_commit_id does not match branch head")
        return _err("CONFLICT", "Branch head does not match last_commit_id.")

    # Decode content: accept either raw UTF-8 string or base64-encoded payload.
    content_bytes = None
    decoded_as_b64 = False
    try:
        # validate=True rejects non-b64 characters; this helps decide if it's b64
        content_bytes = base64.b64decode(content.encode("utf-8"), validate=True)
        decoded_as_b64 = True
    except Exception:
        content_bytes = content.encode("utf-8")

    if len(content_bytes) > 50_000_000:
        _log("error", "VALIDATION_ERROR", "content exceeds max commit size")
        return _err("VALIDATION_ERROR", "content is too large.")

    # Build new tree snapshot
    parent_tree = head_commit.get("tree")
    if not isinstance(parent_tree, dict):
        parent_tree = {}
    new_tree = copy.deepcopy(parent_tree)

    _ensure_dir_entries(new_tree, file_norm)
    new_tree[file_norm] = {
        "type": "file",
        "content_base64": base64.b64encode(content_bytes).decode("ascii"),
        "size_bytes": len(content_bytes),
        "mime": "application/octet-stream",
        "last_modified_at": now,
    }

    # Enforce total materialized size <= 50MB
    total = 0
    for _, meta in new_tree.items():
        if isinstance(meta, dict) and meta.get("type") == "file":
            sb = meta.get("size_bytes")
            if isinstance(sb, int) and sb >= 0:
                total += sb
    if total > 50_000_000:
        _log("error", "VALIDATION_ERROR", "tree exceeds max size per commit")
        return _err("VALIDATION_ERROR", "Commit tree exceeds maximum materialized size.")

    # Create commit and advance branch atomically
    new_commit_id = _new_id("gl_cmt")
    git_sha = base64.b16encode(os.urandom(20)).decode("ascii").lower()

    # Ensure unique(project_id, git_sha)
    while any(isinstance(c, dict) and c.get("project_id") == project_id and c.get("git_sha") == git_sha for c in commits):
        git_sha = base64.b16encode(os.urandom(20)).decode("ascii").lower()

    new_commit = {
        "id": new_commit_id,
        "project_id": project_id,
        "git_sha": git_sha,
        "parent_commit_id": head_commit.get("id"),
        "author_user_id": author_user_id,
        "message": commit_message,
        "status": "created",
        "tree": new_tree,
        "created_at": now,
        "updated_at": now,
    }

    # Persist
    commits.append(new_commit)
    br["head_commit_id"] = new_commit_id
    br["updated_at"] = now
    project["updated_at"] = now

    _save("commits.json", commits)
    _save("branches.json", branches)
    _save("projects.json", projects)

    _log("success")
    return {"commit": new_commit, "branch": br, "project": project, "content_was_base64": decoded_as_b64}

def search_repositories(query, visibility=None, namespace=None, owner_user_id=None, status=None, sort=None, order=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0374000" if __import__("os").path.isdir("./environment_mix/0374000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ulid_alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        import random
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_ulid_alphabet[t % 32])
            t //= 32
        chars = chars[::-1]
        rand = [random.choice(_ulid_alphabet) for _ in range(16)]
        return f"{prefix}_" + "".join(chars + rand)

    def _log(endpoint, status_code, error_code=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": _new_id("gl_req"),
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - start) * 1000),
        })
        _save("request_logs.json", logs)

    # validate
    try:
        if not isinstance(query, str) or query.strip() == "":
            _log("search_repositories", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "query must be a non-empty string.")
        if visibility is not None and visibility not in ("private", "internal", "public"):
            _log("search_repositories", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid visibility.")
        if status is not None and status not in ("active", "archived", "pending_deletion", "deleted"):
            _log("search_repositories", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.")
        if sort is None:
            sort = "updated_at"
        if sort not in ("created_at", "updated_at", "name"):
            _log("search_repositories", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort.")
        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            _log("search_repositories", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid order.")
        if page is None:
            page = 1
        if page_size is None:
            page_size = 20
        if not isinstance(page, int) or page < 1:
            _log("search_repositories", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
        if not isinstance(page_size, int) or not (1 <= page_size <= 100):
            _log("search_repositories", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_size must be between 1 and 100.")
        if namespace is not None and (not isinstance(namespace, str) or namespace.strip() == ""):
            _log("search_repositories", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid namespace.")
        if owner_user_id is not None:
            if not (isinstance(owner_user_id, str) and re.match(r"^gl_user_[0-9A-HJKMNP-TV-Z]{10,}$", owner_user_id)):
                _log("search_repositories", 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid owner_user_id.")
    except Exception:
        _log("search_repositories", 500, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid input.")

    users = _load("users.json")
    projects = _load("projects.json")

    # ambient auth: pick caller as owner_user_id if provided and active; else any active user; else unauthorized
    caller = None
    if owner_user_id is not None:
        caller = next((u for u in users if u.get("id") == owner_user_id and u.get("status") == "active"), None)
    if caller is None:
        caller = next((u for u in users if u.get("status") == "active"), None)
    if caller is None:
        _log("search_repositories", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active user context available.")

    q = query.lower()
    def _matches_text(p):
        hay = " ".join([
            str(p.get("namespace") or ""),
            str(p.get("name") or ""),
            str(p.get("path") or ""),
            str(p.get("description") or ""),
        ]).lower()
        return q in hay

    # rule: status != 'deleted' AND (visibility='public' OR owner_user_id is caller)
    filtered = []
    for p in projects:
        if p.get("status") == "deleted":
            continue
        if not _matches_text(p):
            continue
        if namespace is not None and p.get("namespace") != namespace:
            continue
        if visibility is not None and p.get("visibility") != visibility:
            continue
        if status is not None and p.get("status") != status:
            continue
        if owner_user_id is not None and p.get("owner_user_id") != owner_user_id:
            continue

        allowed = (p.get("visibility") == "public") or (p.get("owner_user_id") == caller.get("id"))
        if not allowed:
            continue
        filtered.append(p)

    # sort
    rev = (order == "desc")
    def _key(p):
        v = p.get(sort)
        if sort in ("created_at", "updated_at"):
            return v or ""
        if sort == "name":
            return (p.get("name") or "").lower()
        return v
    filtered.sort(key=_key, reverse=rev)

    total = len(filtered)
    start_i = (page - 1) * page_size
    end_i = start_i + page_size
    page_items = filtered[start_i:end_i]
    has_more = end_i < total

    _log("search_repositories", 200, None)
    return {
        "projects": page_items,
        "meta": {
            "total": total,
            "page": page,
            "page_size": page_size,
            "has_more": has_more,
        }
    }

def create_repository(owner_user_id, namespace, name, path, visibility, default_branch, description=None, **_extra):
    import json, os, datetime, time, re, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0374000" if __import__("os").path.isdir("./environment_mix/0374000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_ULID32[t % 32])
            t //= 32
        chars = chars[::-1]
        rand = [_ULID32[random.randrange(32)] for _ in range(16)]
        return f"{prefix}_" + "".join(chars + rand)

    def _log(status, error_code=None, message=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": _new_id("gl_req"),
                "endpoint": "create_repository",
                "status": status,
                "error_code": error_code,
                "message": message,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    ulid_usr = re.compile(r"^gl_user_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(owner_user_id, str) or not ulid_usr.match(owner_user_id):
        _log("error", "VALIDATION_ERROR", "owner_user_id is invalid")
        return _err("VALIDATION_ERROR", "owner_user_id is invalid.")
    if not isinstance(namespace, str) or not namespace.strip():
        _log("error", "VALIDATION_ERROR", "namespace is invalid")
        return _err("VALIDATION_ERROR", "namespace is required.")
    if not isinstance(name, str) or not (1 <= len(name.strip()) <= 255):
        _log("error", "VALIDATION_ERROR", "name is invalid")
        return _err("VALIDATION_ERROR", "name must be 1..255 characters.")
    if not isinstance(path, str) or not (1 <= len(path.strip()) <= 255):
        _log("error", "VALIDATION_ERROR", "path is invalid")
        return _err("VALIDATION_ERROR", "path must be 1..255 characters.")
    if visibility not in ("private", "internal", "public"):
        _log("error", "VALIDATION_ERROR", "visibility is invalid")
        return _err("VALIDATION_ERROR", "visibility must be one of: private, internal, public.")
    if not isinstance(default_branch, str) or not (1 <= len(default_branch.strip()) <= 255):
        _log("error", "VALIDATION_ERROR", "default_branch is invalid")
        return _err("VALIDATION_ERROR", "default_branch must be 1..255 characters.")
    if description is not None and not isinstance(description, str):
        _log("error", "VALIDATION_ERROR", "description is invalid")
        return _err("VALIDATION_ERROR", "description must be a string.")

    users = _load("users.json")
    owner = next((u for u in users if isinstance(u, dict) and u.get("id") == owner_user_id), None)
    if not owner or owner.get("status") == "deleted":
        _log("error", "NOT_FOUND", "owner user not found")
        return _err("NOT_FOUND", "owner_user_id not found.")
    if owner.get("status") != "active":
        _log("error", "UNAUTHORIZED", "owner user not active")
        return _err("UNAUTHORIZED", "Owner user is not active.")

    projects = _load("projects.json")
    ns = namespace.strip()
    pth = path.strip()

    # unique(namespace, path) among non-deleted projects
    for p in projects:
        if isinstance(p, dict) and p.get("namespace") == ns and p.get("path") == pth and p.get("status") != "deleted":
            _log("error", "CONFLICT", "namespace/path already exists")
            return _err("CONFLICT", "A project with this namespace and path already exists.")

    # Create initial commit and default branch
    project_id = _new_id("gl_prj")
    commit_id = _new_id("gl_cmt")
    branch_id = _new_id("gl_br")

    git_sha = base64.b16encode(os.urandom(20)).decode("ascii").lower()
    commits = _load("commits.json")
    while any(isinstance(c, dict) and c.get("project_id") == project_id and c.get("git_sha") == git_sha for c in commits):
        git_sha = base64.b16encode(os.urandom(20)).decode("ascii").lower()

    initial_commit = {
        "id": commit_id,
        "project_id": project_id,
        "git_sha": git_sha,
        "parent_commit_id": None,
        "author_user_id": owner_user_id,
        "message": "Initial commit",
        "status": "created",
        "tree": {},
        "created_at": now,
        "updated_at": now,
    }

    new_project = {
        "id": project_id,
        "owner_user_id": owner_user_id,
        "namespace": ns,
        "name": name.strip(),
        "path": pth,
        "description": description,
        "visibility": visibility,
        "default_branch": default_branch.strip(),
        "forked_from_project_id": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    new_branch = {
        "id": branch_id,
        "project_id": project_id,
        "name": new_project["default_branch"],
        "head_commit_id": commit_id,
        "protected": False,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Enforce default_branch exists as active branch
    branches = _load("branches.json")
    # unique(project_id, name)
    if any(isinstance(b, dict) and b.get("project_id") == project_id and b.get("name") == new_branch["name"] and b.get("status") != "deleted" for b in branches):
        _log("error", "CONFLICT", "default branch already exists unexpectedly")
        return _err("CONFLICT", "Branch already exists.")

    projects.append(new_project)
    commits.append(initial_commit)
    branches.append(new_branch)

    _save("projects.json", projects)
    _save("commits.json", commits)
    _save("branches.json", branches)

    _log("success")
    return {"project": new_project, "default_branch": new_branch, "initial_commit": initial_commit}

def get_file_contents(project_id, ref, path, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0374000" if __import__("os").path.isdir("./environment_mix/0374000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        import random
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_ULID32[t % 32])
            t //= 32
        chars = chars[::-1]
        rand = [_ULID32[random.randrange(32)] for _ in range(16)]
        return f"{prefix}_" + "".join(chars + rand)

    def _log(status, error_code=None, message=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": _new_id("gl_req"),
                "endpoint": "get_file_contents",
                "status": status,
                "error_code": error_code,
                "message": message,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _norm_path(p):
        if not isinstance(p, str) or p.strip() == "":
            return None, "path must be a non-empty string"
        p = p.replace("\\", "/").strip()
        while p.startswith("/"):
            p = p[1:]
        parts = [seg for seg in p.split("/") if seg not in ("", ".")]
        if any(seg == ".." for seg in parts):
            return None, "path must not contain '..' segments"
        return "/".join(parts), None

    def _dir_listing(tree, dir_path):
        prefix = "" if dir_path == "" else dir_path.rstrip("/") + "/"
        children = set()
        for k in tree.keys():
            if not isinstance(k, str):
                continue
            if not k.startswith(prefix) or k == dir_path:
                continue
            rest = k[len(prefix):]
            if rest == "":
                continue
            first = rest.split("/", 1)[0]
            child_path = prefix + first if prefix else first
            children.add(child_path)
        out = []
        for cp in sorted(children):
            meta = tree.get(cp)
            if isinstance(meta, dict) and meta.get("type") in ("file", "dir"):
                out.append({"path": cp, "type": meta.get("type")})
            else:
                out.append({"path": cp, "type": "dir"})
        return out

    ulid_prj = re.compile(r"^gl_prj_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_cmt = re.compile(r"^gl_cmt_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(project_id, str) or not ulid_prj.match(project_id):
        _log("error", "VALIDATION_ERROR", "project_id is invalid")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if not isinstance(ref, str) or ref.strip() == "":
        _log("error", "VALIDATION_ERROR", "ref is invalid")
        return _err("VALIDATION_ERROR", "ref must be a non-empty string.")
    if not isinstance(path, str) or path.strip() == "":
        _log("error", "VALIDATION_ERROR", "path is invalid")
        return _err("VALIDATION_ERROR", "path must be a non-empty string.")

    norm_path, perr = _norm_path(path)
    if perr:
        _log("error", "VALIDATION_ERROR", perr)
        return _err("VALIDATION_ERROR", perr)

    projects = _load("projects.json")
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not project or project.get("status") == "deleted":
        _log("error", "NOT_FOUND", "project not found")
        return _err("NOT_FOUND", "project not found.")

    # Resolve ref: try branch name first (common), then commit id, then git_sha
    branches = _load("branches.json")
    commits = _load("commits.json")

    commit = None
    b = next((br for br in branches if isinstance(br, dict) and br.get("project_id") == project_id and br.get("name") == ref and br.get("status") == "active"), None)
    if b:
        commit = next((c for c in commits if isinstance(c, dict) and c.get("id") == b.get("head_commit_id") and c.get("project_id") == project_id), None)
    if commit is None and ulid_cmt.match(ref):
        commit = next((c for c in commits if isinstance(c, dict) and c.get("id") == ref and c.get("project_id") == project_id), None)
    if commit is None:
        # treat as git sha (unique within project)
        commit = next((c for c in commits if isinstance(c, dict) and c.get("project_id") == project_id and c.get("git_sha") == ref), None)

    if commit is None:
        _log("error", "NOT_FOUND", "ref could not be resolved")
        return _err("NOT_FOUND", "ref could not be resolved.")

    tree = commit.get("tree")
    if not isinstance(tree, dict):
        tree = {}

    # Exact match first
    meta = tree.get(norm_path)
    if isinstance(meta, dict) and meta.get("type") == "file":
        cb64 = meta.get("content_base64")
        if not isinstance(cb64, str):
            _log("error", "NOT_FOUND", "file missing content")
            return _err("NOT_FOUND", "path does not exist at ref.")
        _log("success")
        return {
            "ref": ref,
            "commit_id": commit.get("id"),
            "path": norm_path,
            "type": "file",
            "content_base64": cb64,
            "size_bytes": meta.get("size_bytes"),
            "last_modified_at": meta.get("last_modified_at"),
        }

    # Directory: explicit dir entry OR implied by children
    is_dir = isinstance(meta, dict) and meta.get("type") == "dir"
    if not is_dir:
        prefix = "" if norm_path == "" else norm_path.rstrip("/") + "/"
        is_dir = any(isinstance(k, str) and k.startswith(prefix) for k in tree.keys())

    if is_dir:
        listing = _dir_listing(tree, norm_path)
        _log("success")
        return {
            "ref": ref,
            "commit_id": commit.get("id"),
            "path": norm_path,
            "type": "dir",
            "entries": listing,
        }

    _log("error", "NOT_FOUND", "path not found at ref")
    return _err("NOT_FOUND", "path does not exist at ref.")

def push_files(project_id, branch, commit_message, author_user_id, files, last_commit_id=None, **_extra):
    import json, os, datetime, re, base64, time, random, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0374000" if __import__("os").path.isdir("./environment_mix/0374000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    _ULID32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_ULID32[t % 32])
            t //= 32
        chars = chars[::-1]
        rand = [_ULID32[random.randrange(32)] for _ in range(16)]
        return f"{prefix}_" + "".join(chars + rand)

    def _log(status, error_code=None, message=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": _new_id("gl_req"),
                "endpoint": "push_files",
                "status": status,
                "error_code": error_code,
                "message": message,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _norm_path(p):
        if not isinstance(p, str) or p.strip() == "":
            return None, "path must be a non-empty string"
        p = p.replace("\\", "/").strip()
        while p.startswith("/"):
            p = p[1:]
        parts = [seg for seg in p.split("/") if seg not in ("", ".")]
        if any(seg == ".." for seg in parts):
            return None, "path must not contain '..' segments"
        return "/".join(parts), None

    ulid_prj = re.compile(r"^gl_prj_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_usr = re.compile(r"^gl_user_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_cmt = re.compile(r"^gl_cmt_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(project_id, str) or not ulid_prj.match(project_id):
        _log("error", "VALIDATION_ERROR", "project_id is invalid")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if not isinstance(branch, str) or branch.strip() == "":
        _log("error", "VALIDATION_ERROR", "branch is invalid")
        return _err("VALIDATION_ERROR", "branch must be a non-empty string.")
    if not isinstance(commit_message, str) or not (1 <= len(commit_message) <= 2000):
        _log("error", "VALIDATION_ERROR", "commit_message is invalid")
        return _err("VALIDATION_ERROR", "commit_message must be 1..2000 characters.")
    if not isinstance(author_user_id, str) or not ulid_usr.match(author_user_id):
        _log("error", "VALIDATION_ERROR", "author_user_id is invalid")
        return _err("VALIDATION_ERROR", "author_user_id is invalid.")
    if not isinstance(files, list) or len(files) < 1:
        _log("error", "VALIDATION_ERROR", "files is invalid")
        return _err("VALIDATION_ERROR", "files must be a non-empty list.")
    if last_commit_id is not None:
        if not isinstance(last_commit_id, str) or last_commit_id.strip() == "":
            _log("error", "VALIDATION_ERROR", "last_commit_id is invalid")
            return _err("VALIDATION_ERROR", "last_commit_id is invalid.")
        if not ulid_cmt.match(last_commit_id):
            last_commit_id = None  # relax like create_or_update_file

    users = _load("users.json")
    author = next((u for u in users if isinstance(u, dict) and u.get("id") == author_user_id), None)
    if not author or author.get("status") != "active":
        _log("error", "NOT_FOUND", "author_user_id not found or not active")
        return _err("NOT_FOUND", "author_user_id not found.")

    projects = _load("projects.json")
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not project or project.get("status") == "deleted":
        _log("error", "NOT_FOUND", "project not found")
        return _err("NOT_FOUND", "project not found.")

    branches = _load("branches.json")
    br = next((b for b in branches if isinstance(b, dict) and b.get("project_id") == project_id and b.get("name") == branch and b.get("status") == "active"), None)
    if not br:
        _log("error", "NOT_FOUND", "branch not found")
        return _err("NOT_FOUND", "branch not found.")

    commits = _load("commits.json")
    head_commit = next((c for c in commits if isinstance(c, dict) and c.get("id") == br.get("head_commit_id")), None)
    if not head_commit or head_commit.get("project_id") != project_id:
        _log("error", "CONFLICT", "branch head commit missing or mismatched")
        return _err("CONFLICT", "Branch head commit is missing or invalid.")

    if last_commit_id is not None and br.get("head_commit_id") != last_commit_id:
        _log("error", "CONFLICT", "last_commit_id does not match branch head")
        return _err("CONFLICT", "Branch head does not match last_commit_id.")

    # Validate all file operations first (atomicity)
    normalized_updates = []
    seen_paths = set()
    total_new_bytes = 0
    for i, f in enumerate(files):
        if not isinstance(f, dict):
            _log("error", "VALIDATION_ERROR", "invalid file entry")
            return _err("VALIDATION_ERROR", f"files[{i}] must be an object.")
        if set(f.keys()) != {"file_path", "content"}:
            _log("error", "VALIDATION_ERROR", "invalid file entry fields")
            return _err("VALIDATION_ERROR", f"files[{i}] must contain only file_path and content.")
        fp = f.get("file_path")
        ct = f.get("content")
        nfp, perr = _norm_path(fp)
        if perr:
            _log("error", "VALIDATION_ERROR", perr)
            return _err("VALIDATION_ERROR", f"files[{i}].file_path: {perr}")
        if nfp in seen_paths:
            _log("error", "VALIDATION_ERROR", "duplicate file_path in request")
            return _err("VALIDATION_ERROR", f"Duplicate file_path in files: {nfp}")
        seen_paths.add(nfp)
        if not isinstance(ct, str):
            _log("error", "VALIDATION_ERROR", "content must be string")
            return _err("VALIDATION_ERROR", f"files[{i}].content must be a string.")

        # accept base64 or raw string
        try:
            b = base64.b64decode(ct.encode("utf-8"), validate=True)
        except Exception:
            b = ct.encode("utf-8")

        if len(b) > 50_000_000:
            _log("error", "VALIDATION_ERROR", "single file too large")
            return _err("VALIDATION_ERROR", f"files[{i}] content is too large.")
        total_new_bytes += len(b)
        normalized_updates.append((nfp, b))

    parent_tree = head_commit.get("tree")
    if not isinstance(parent_tree, dict):
        parent_tree = {}
    new_tree = copy.deepcopy(parent_tree)

    # Apply changes
    for nfp, b in normalized_updates:
        # ensure dir entries for listings
        segs = nfp.split("/")[:-1]
        cur = ""
        for s in segs:
            cur = s if cur == "" else (cur + "/" + s)
            if cur not in new_tree:
                new_tree[cur] = {"type": "dir", "last_modified_at": now}
        new_tree[nfp] = {
            "type": "file",
            "content_base64": base64.b64encode(b).decode("ascii"),
            "size_bytes": len(b),
            "mime": "application/octet-stream",
            "last_modified_at": now,
        }

    # Enforce total materialized size <= 50MB
    total = 0
    for _, meta in new_tree.items():
        if isinstance(meta, dict) and meta.get("type") == "file":
            sb = meta.get("size_bytes")
            if isinstance(sb, int) and sb >= 0:
                total += sb
    if total > 50_000_000:
        _log("error", "VALIDATION_ERROR", "tree exceeds max size per commit")
        return _err("VALIDATION_ERROR", "Commit tree exceeds maximum materialized size.")

    new_commit_id = _new_id("gl_cmt")
    git_sha = base64.b16encode(os.urandom(20)).decode("ascii").lower()
    while any(isinstance(c, dict) and c.get("project_id") == project_id and c.get("git_sha") == git_sha for c in commits):
        git_sha = base64.b16encode(os.urandom(20)).decode("ascii").lower()

    new_commit = {
        "id": new_commit_id,
        "project_id": project_id,
        "git_sha": git_sha,
        "parent_commit_id": head_commit.get("id"),
        "author_user_id": author_user_id,
        "message": commit_message,
        "status": "created",
        "tree": new_tree,
        "created_at": now,
        "updated_at": now,
    }

    commits.append(new_commit)
    br["head_commit_id"] = new_commit_id
    br["updated_at"] = now
    project["updated_at"] = now

    _save("commits.json", commits)
    _save("branches.json", branches)
    _save("projects.json", projects)

    _log("success")
    return {"commit": new_commit, "branch": br, "project": project, "files_applied": len(normalized_updates)}

def create_issue(project_id, title, author_user_id, description=None, assignee_user_id=None, state=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0374000" if __import__("os").path.isdir("./environment_mix/0374000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential=None, error_code=None):
        fname = "request_logs.json"
        if not os.path.exists(os.path.join(_DB, fname)):
            return
        logs = _load(fname)
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "create_issue",
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        })
        _save(fname, logs)

    ulid_prj = re.compile(r"^gl_prj_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_usr = re.compile(r"^gl_user_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(project_id, str) or not ulid_prj.match(project_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid project_id.")
    if not isinstance(title, str) or not (1 <= len(title) <= 255):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid title (must be 1..255 chars).")
    if description is not None and not isinstance(description, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid description.")
    if not isinstance(author_user_id, str) or not ulid_usr.match(author_user_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid author_user_id.")
    if assignee_user_id is not None and (not isinstance(assignee_user_id, str) or not ulid_usr.match(assignee_user_id)):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid assignee_user_id.")
    if state is None:
        state = "opened"
    if state not in ("opened", "closed"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid state.")

    users = _load("users.json")
    projects = _load("projects.json")
    issues = _load("issues.json")

    project = next((p for p in projects if p.get("id") == project_id), None)
    if not project or project.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.")
    if project.get("status") not in ("active", "archived"):
        _log("error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Project must be active or archived to create issues.")

    author = next((u for u in users if u.get("id") == author_user_id), None)
    if not author or author.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Author user not found.")
    if author.get("status") != "active":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Author user must be active.")

    if assignee_user_id is not None:
        assignee = next((u for u in users if u.get("id") == assignee_user_id), None)
        if not assignee or assignee.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Assignee user not found.")
        if assignee.get("status") != "active":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Assignee user must be active.")

    # "FORBIDDEN" mentioned in tool text, but allowed codes list doesn't include it.
    # Use UNAUTHORIZED when no valid context; for this datastore, enforce basic rule: private/internal projects require owner.
    vis = project.get("visibility")
    if vis in ("private", "internal") and project.get("owner_user_id") != author_user_id:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not permitted to create issues in this project.")

    # Allocate next iid per project
    max_iid = 0
    for it in issues:
        if it.get("project_id") == project_id and it.get("status") != "deleted":
            iid = it.get("iid")
            if isinstance(iid, int) and iid > max_iid:
                max_iid = iid
    next_iid = max_iid + 1
    if next_iid < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid iid allocation.")

    # Generate id
    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    import random
    def _ulid_like(prefix):
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(16))
    new_id = _ulid_like("gl_iss")
    existing_ids = {x.get("id") for x in issues}
    while new_id in existing_ids:
        new_id = _ulid_like("gl_iss")

    issue = {
        "id": new_id,
        "project_id": project_id,
        "iid": next_iid,
        "title": title,
        "description": description,
        "author_user_id": author_user_id,
        "assignee_user_id": assignee_user_id,
        "state": state,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # Enforce unique(project_id, iid)
    if any(x.get("project_id") == project_id and x.get("iid") == next_iid for x in issues):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Issue iid conflict; please retry.")

    issues.append(issue)
    _save("issues.json", issues)

    _log("ok")
    return {"issue": issue}

