    author = next((u for u in users if isinstance(u, dict) and u.get("id") == author_user_id), None)
    if not author or author.get("status") != "active":
        _log("error", "NOT_FOUND", "author user not found/active")
        return _err("NOT_FOUND", "author_user_id not found.")

    projects = _load("projects.json")
    sp = next((p for p in projects if isinstance(p, dict) and p.get("id") == source_project_id), None)
    tp = next((p for p in projects if isinstance(p, dict) and p.get("id") == target_project_id), None)
    if not sp or sp.get("status") == "deleted":
        _log("error", "NOT_FOUND", "source project not found")
        return _err("NOT_FOUND", "source_project_id not found.")
    if not tp or tp.get("status") == "deleted":
        _log("error", "NOT_FOUND", "target project not found")
        return _err("NOT_FOUND", "target_project_id not found.")
    if sp.get("status") not in ("active", "archived") or tp.get("status") not in ("active", "archived"):
        _log("error", "VALIDATION_ERROR", "project status invalid for MR")
        return _err("VALIDATION_ERROR", "source_project_id and target_project_id must be active or archived.")

    branches = _load("branches.json")
    sbr = next((b for b in branches if isinstance(b, dict) and b.get("project_id") == source_project_id and b.get("name") == source_branch and b.get("status") == "active"), None)
    tbr = next((b for b in branches if isinstance(b, dict) and b.get("project_id") == target_project_id and b.get("name") == target_branch and b.get("status") == "active"), None)
    if not sbr:
        _log("error", "NOT_FOUND", "source branch not found")
        return _err("NOT_FOUND", "source_branch not found.")
    if not tbr:
        _log("error", "NOT_FOUND", "target branch not found")
        return _err("NOT_FOUND", "target_branch not found.")

    commits = _load("commits.json")
    source_head = next((c for c in commits if isinstance(c, dict) and c.get("id") == sbr.get("head_commit_id") and c.get("project_id") == source_project_id), None)
    target_head = next((c for c in commits if isinstance(c, dict) and c.get("id") == tbr.get("head_commit_id") and c.get("project_id") == target_project_id), None)
    if not source_head:
        _log("error", "CONFLICT", "source head commit missing")
        return _err("CONFLICT", "source_head_commit_id could not be resolved.")
    if not target_head:
        _log("error", "CONFLICT", "target base commit missing")
        return _err("CONFLICT", "target_base_commit_id could not be resolved.")

    mrs = _load("merge_requests.json")
    # allocate next iid per target_project_id
    max_iid = 0
    for mr in mrs:
        if isinstance(mr, dict) and mr.get("target_project_id") == target_project_id and isinstance(mr.get("iid"), int):
            if mr["iid"] > max_iid:
                max_iid = mr["iid"]
    new_iid = max_iid + 1
    if new_iid < 1:
        new_iid = 1

    new_mr = {
        "id": _new_id("gl_mr"),
        "target_project_id": target_project_id,
        "source_project_id": source_project_id,
        "iid": new_iid,
        "title": title,
        "description": description,
        "author_user_id": author_user_id,
        "source_branch": source_branch,
        "target_branch": target_branch,
        "source_head_commit_id": source_head.get("id"),
        "target_base_commit_id": target_head.get("id"),
        "state": "opened",
        "merge_status": "unchecked",
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    mrs.append(new_mr)
    _save("merge_requests.json", mrs)
    _log("success")
    return {"merge_request": new_mr}

def fork_repository(project_id, owner_user_id, namespace=None, name=None, path=None, visibility=None, **_extra):
    import json, os, datetime, re, time, random, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0374000" if __import__("os").path.isdir("./environment_mix/0374000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_ULID32[t % 32])
            t //= 32
        chars = chars[::-1]
        rand = [_ULID32[random.randrange(32)] for _ in range(16)]
        return f"{prefix}_" + "".join(chars + rand)

    def _log(status, error_code=None, message=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": _new_id("gl_req"),
                "endpoint": "fork_repository",
                "status": status,
                "error_code": error_code,
                "message": message,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    ulid_prj = re.compile(r"^gl_prj_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_usr = re.compile(r"^gl_user_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(project_id, str) or not ulid_prj.match(project_id):
        _log("error", "VALIDATION_ERROR", "project_id is invalid")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if not isinstance(owner_user_id, str) or not ulid_usr.match(owner_user_id):
        _log("error", "VALIDATION_ERROR", "owner_user_id is invalid")
        return _err("VALIDATION_ERROR", "owner_user_id is invalid.")
    if namespace is not None and (not isinstance(namespace, str) or not namespace.strip()):
        _log("error", "VALIDATION_ERROR", "namespace is invalid")
        return _err("VALIDATION_ERROR", "namespace must be a non-empty string.")
    if name is not None and (not isinstance(name, str) or not name.strip() or len(name.strip()) > 255):
        _log("error", "VALIDATION_ERROR", "name is invalid")
        return _err("VALIDATION_ERROR", "name must be 1..255 characters.")
    if path is not None and (not isinstance(path, str) or not path.strip() or len(path.strip()) > 255):
        _log("error", "VALIDATION_ERROR", "path is invalid")
        return _err("VALIDATION_ERROR", "path must be 1..255 characters.")
    if visibility is not None and visibility not in ("private", "internal", "public"):
        _log("error", "VALIDATION_ERROR", "visibility is invalid")
        return _err("VALIDATION_ERROR", "visibility must be one of: private, internal, public.")

    users = _load("users.json")
    owner = next((u for u in users if isinstance(u, dict) and u.get("id") == owner_user_id), None)
    if not owner or owner.get("status") == "deleted":
        _log("error", "NOT_FOUND", "owner user not found")
        return _err("NOT_FOUND", "owner_user_id not found.")
    if owner.get("status") != "active":
        _log("error", "UNAUTHORIZED", "owner not active")
        return _err("UNAUTHORIZED", "Owner user is not active.")

    projects = _load("projects.json")
    upstream = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not upstream or upstream.get("status") == "deleted":
        _log("error", "NOT_FOUND", "upstream project not found")
        return _err("NOT_FOUND", "project_id not found.")
    if upstream.get("status") not in ("active", "archived"):
        _log("error", "VALIDATION_ERROR", "upstream must be active or archived")
        return _err("VALIDATION_ERROR", "Source project must be active or archived to fork.")

    dst_namespace = namespace.strip() if isinstance(namespace, str) and namespace.strip() else owner.get("username")
    dst_name = name.strip() if isinstance(name, str) and name.strip() else upstream.get("name")
    dst_path = path.strip() if isinstance(path, str) and path.strip() else upstream.get("path")
    dst_visibility = visibility if visibility is not None else upstream.get("visibility", "private")

    # unique(namespace, path) among non-deleted
    for p in projects:
        if isinstance(p, dict) and p.get("namespace") == dst_namespace and p.get("path") == dst_path and p.get("status") != "deleted":
            _log("error", "CONFLICT", "namespace/path already exists")
            return _err("CONFLICT", "A project with this namespace and path already exists.")

    branches = _load("branches.json")
    commits = _load("commits.json")

    # Copy upstream default branch and its head commit as fork initial head
    up_default = upstream.get("default_branch")
    up_branch = next((b for b in branches if isinstance(b, dict) and b.get("project_id") == project_id and b.get("name") == up_default and b.get("status") == "active"), None)
    if not up_branch:
        _log("error", "CONFLICT", "upstream default branch missing")
        return _err("CONFLICT", "Upstream default branch is missing or not active.")
    up_head_commit = next((c for c in commits if isinstance(c, dict) and c.get("id") == up_branch.get("head_commit_id") and c.get("project_id") == project_id), None)
    if not up_head_commit:
        _log("error", "CONFLICT", "upstream head commit missing")
        return _err("CONFLICT", "Upstream head commit is missing.")

    new_project_id = _new_id("gl_prj")
    new_project = {
        "id": new_project_id,
        "owner_user_id": owner_user_id,
        "namespace": dst_namespace,
        "name": dst_name,
        "path": dst_path,
        "description": upstream.get("description"),
        "visibility": dst_visibility,
        "default_branch": up_default,
        "forked_from_project_id": project_id,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Fork uses same commit snapshot content; create a new commit row in the fork project as the initial commit
    # (simplified model). Parent is None as fork root.
    new_commit_id = _new_id("gl_cmt")
    new_git_sha = up_head_commit.get("git_sha")
    # ensure unique(project_id, git_sha)
    if any(isinstance(c, dict) and c.get("project_id") == new_project_id and c.get("git_sha") == new_git_sha for c in commits):
        # if collision, generate a new sha
        import os as _os, base64 as _base64
        new_git_sha = _base64.b16encode(_os.urandom(20)).decode("ascii").lower()

    new_commit = {
        "id": new_commit_id,
        "project_id": new_project_id,
        "git_sha": new_git_sha,
        "parent_commit_id": None,
        "author_user_id": up_head_commit.get("author_user_id") or owner_user_id,
        "message": "Forked from " + (upstream.get("path") or "upstream"),
        "status": "created",
        "tree": copy.deepcopy(up_head_commit.get("tree") if isinstance(up_head_commit.get("tree"), dict) else {}),
        "created_at": now,
        "updated_at": now,
    }

    new_branch = {
        "id": _new_id("gl_br"),
        "project_id": new_project_id,
        "name": up_default,
        "head_commit_id": new_commit_id,
        "protected": False,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    projects.append(new_project)
    commits.append(new_commit)
    branches.append(new_branch)

    _save("projects.json", projects)
    _save("commits.json", commits)
    _save("branches.json", branches)

    _log("success")
    return {"project": new_project, "default_branch": new_branch, "initial_commit": new_commit}

def create_branch(project_id, name, ref, protected=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0374000" if __import__("os").path.isdir("./environment_mix/0374000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_ULID32[t % 32])
            t //= 32
        chars = chars[::-1]
        rand = [_ULID32[random.randrange(32)] for _ in range(16)]
        return f"{prefix}_" + "".join(chars + rand)

    def _log(status, error_code=None, message=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": _new_id("gl_req"),
                "endpoint": "create_branch",
                "status": status,
                "error_code": error_code,
                "message": message,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    ulid_prj = re.compile(r"^gl_prj_[0-9A-HJKMNP-TV-Z]{10,}$")
    ulid_cmt = re.compile(r"^gl_cmt_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(project_id, str) or not ulid_prj.match(project_id):
        _log("error", "VALIDATION_ERROR", "project_id is invalid")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if not isinstance(name, str) or len(name.strip()) < 1 or len(name) > 255:
        _log("error", "VALIDATION_ERROR", "name is invalid")
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 255 characters.")
    if not isinstance(ref, str) or len(ref.strip()) < 1:
        _log("error", "VALIDATION_ERROR", "ref is invalid")
        return _err("VALIDATION_ERROR", "ref must be a non-empty string.")
    if protected is not None and not isinstance(protected, bool):
        _log("error", "VALIDATION_ERROR", "protected is invalid")
        return _err("VALIDATION_ERROR", "protected must be a boolean.")

    projects = _load("projects.json")
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not project or project.get("status") == "deleted":
        _log("error", "NOT_FOUND", "project not found")
        return _err("NOT_FOUND", "project not found.")
    if project.get("status") != "active":
        _log("error", "VALIDATION_ERROR", "project must be active to create branch")
        return _err("VALIDATION_ERROR", "project must be status='active' to create branch.")

    branches = _load("branches.json")
    if any(isinstance(b, dict) and b.get("project_id") == project_id and b.get("name") == name and b.get("status") != "deleted" for b in branches):
        _log("error", "CONFLICT", "branch already exists")
        return _err("CONFLICT", "A branch with this name already exists in the project.")

    commits = _load("commits.json")

    # Resolve ref: branch name -> head commit; commit id; git_sha
    base_commit = None
    rb = next((b for b in branches if isinstance(b, dict) and b.get("project_id") == project_id and b.get("name") == ref and b.get("status") == "active"), None)
    if rb:
        base_commit = next((c for c in commits if isinstance(c, dict) and c.get("id") == rb.get("head_commit_id") and c.get("project_id") == project_id), None)
    if base_commit is None and ulid_cmt.match(ref):
        base_commit = next((c for c in commits if isinstance(c, dict) and c.get("id") == ref and c.get("project_id") == project_id), None)
    if base_commit is None:
        base_commit = next((c for c in commits if isinstance(c, dict) and c.get("project_id") == project_id and c.get("git_sha") == ref), None)

    if base_commit is None:
        _log("error", "NOT_FOUND", "ref could not be resolved")
        return _err("NOT_FOUND", "ref could not be resolved to an existing branch/commit in the project.")

    new_branch = {
        "id": _new_id("gl_br"),
        "project_id": project_id,
        "name": name,
        "head_commit_id": base_commit.get("id"),
        "protected": bool(protected) if protected is not None else False,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    branches.append(new_branch)
    project["updated_at"] = now
    _save("branches.json", branches)
    _save("projects.json", projects)

    _log("success")
    return {"branch": new_branch, "project": project, "ref_commit": base_commit}

def get_current_user(access_token, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0374000" if __import__("os").path.isdir("./environment_mix/0374000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential=None, message=None):
        for fname in ("request_logs.json", "usage.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                rows.append({
                    "id": "gl_req_" + secrets.token_hex(12),
                    "endpoint": "get_current_user",
                    "credential": credential,
                    "status": status_code,
                    "message": message,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now
                })
                _save(fname, rows)
                break

    if not isinstance(access_token, str) or not access_token:
        _log("VALIDATION_ERROR", None, "missing access_token")
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string.")

    # Try to authenticate from tokens.json / access_tokens.json / api_keys.json if present.
    token_row = None
    token_file = None
    for fname in ("access_tokens.json", "tokens.json", "api_keys.json"):
        if os.path.exists(os.path.join(_DB, fname)):
            rows = _load(fname)
            # Authenticate by client-visible token value OR id (per contract)
            token_row = next((r for r in rows if r.get("token") == access_token or r.get("access_token") == access_token or r.get("key") == access_token or r.get("id") == access_token), None)
            if token_row:
                token_file = fname
                break

    users = _load("users.json")

    caller = None
    scopes = []
    if token_row:
        uid = token_row.get("user_id") or token_row.get("owner_user_id") or token_row.get("subject_user_id")
        if isinstance(token_row.get("scopes"), list):
            scopes = token_row.get("scopes")
        elif isinstance(token_row.get("scope"), str):
            scopes = [s for s in token_row.get("scope").split() if s]
        if uid:
            caller = next((u for u in users if u.get("id") == uid), None)

    # Fallback: allow using a user id directly as token only if it exists and active
    if not caller:
        u = next((u for u in users if u.get("id") == access_token), None)
        if u and u.get("status") == "active":
            caller = u
            scopes = ["api"]

    if not caller or caller.get("status") != "active":
        _log("UNAUTHORIZED", access_token, "invalid credentials")
        return _err("UNAUTHORIZED", "Invalid or missing credentials.")

    # Rate-limit/quota counters: if request log exists, summarize last minute/day; else empty
    counters = {}
    log_rows = None
    for fname in ("request_logs.json", "usage.json"):
        if os.path.exists(os.path.join(_DB, fname)):
            log_rows = _load(fname)
            break
    if isinstance(log_rows, list):
        # naive counters by credential or user_id, last 60s and last 24h
        import datetime as _dt
        def _parse(ts):
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    return _dt.datetime.fromisoformat(ts[:-1])
                if isinstance(ts, str):
                    return _dt.datetime.fromisoformat(ts)
            except Exception:
                return None
            return None
        now_dt = _dt.datetime.utcnow()
        last_min = 0
        last_day = 0
        for r in log_rows:
            ts = _parse(r.get("created_at"))
            if not ts:
                continue
            cred = r.get("credential")
            # best-effort attribution; if token file exists, log uses token; otherwise may be None
            if cred not in (access_token, None) and token_row:
                # if log stored token_row id, allow match
                if cred != token_row.get("id"):
                    continue
            if now_dt - ts <= _dt.timedelta(seconds=60):
                last_min += 1
            if now_dt - ts <= _dt.timedelta(days=1):
                last_day += 1
        counters = {
            "requests_last_60s": last_min,
            "requests_last_24h": last_day
        }

    _log("200", access_token if token_row else caller.get("id"), "ok")
    return {
        "user": caller,
        "scopes": scopes,
        "rate_limit": {
            "counters": counters
        },
        "credential": {
            "type": "access_token",
            "source": token_file if token_file else "users.json_fallback",
            "id": token_row.get("id") if token_row else caller.get("id")
        }
    }

