    include_deleted = bool(include_deleted) if include_deleted is not None else False

    # Authenticate
    users = _load("users.json")
    token_row = None
    for fname in ("access_tokens.json", "tokens.json", "api_keys.json"):
        if os.path.exists(os.path.join(_DB, fname)):
            rows = _load(fname)
            token_row = next((r for r in rows if r.get("token") == access_token or r.get("access_token") == access_token or r.get("key") == access_token or r.get("id") == access_token), None)
            if token_row:
                break

    caller = None
    if token_row:
        uid = token_row.get("user_id") or token_row.get("owner_user_id") or token_row.get("subject_user_id")
        if uid:
            caller = next((u for u in users if u.get("id") == uid), None)
    if not caller:
        u = next((u for u in users if u.get("id") == access_token), None)
        if u and u.get("status") == "active":
            caller = u
    if not caller or caller.get("status") != "active":
        _log("UNAUTHORIZED", access_token, "invalid credentials")
        return _err("UNAUTHORIZED", "Invalid or missing credentials.")

    projects = _load("projects.json")
    prj = next((p for p in projects if p.get("id") == project_id), None)
    if not prj:
        _log("NOT_FOUND", access_token, "project not found")
        return _err("NOT_FOUND", "Project not found.")
    if prj.get("status") == "deleted" and not include_deleted:
        _log("NOT_FOUND", access_token, "project deleted and not included")
        return _err("NOT_FOUND", "Project not found.")

    # Authorization: allow if public OR caller is owner
    if not (prj.get("visibility") == "public" or prj.get("owner_user_id") == caller.get("id")):
        _log("UNAUTHORIZED", access_token, "forbidden")
        return _err("UNAUTHORIZED", "Forbidden.")

    _log("200", access_token, "ok")
    return {"project": prj}

def update_merge_request_state(access_token, merge_request_id, state_event, merged_by_user_id=None, merge_commit_message=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0374000" if __import__("os").path.isdir("./environment_mix/0374000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _ULID32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_ULID32[t % 32])
            t //= 32
        chars = chars[::-1]
        rand = [_ULID32[random.randrange(32)] for _ in range(16)]
        return f"{prefix}_" + "".join(chars + rand)

    def _log(status, error_code=None, message=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": _new_id("gl_req"),
                "endpoint": "update_merge_request_state",
                "status": status,
                "error_code": error_code,
                "message": message,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(access_token, str) or not access_token.strip():
        _log("error", "VALIDATION_ERROR", "access_token is invalid")
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string.")
    if not isinstance(merge_request_id, str) or not re.match(r"^gl_mr_[0-9A-HJKMNP-TV-Z]{10,}$", merge_request_id):
        _log("error", "VALIDATION_ERROR", "merge_request_id is invalid")
        return _err("VALIDATION_ERROR", "merge_request_id is invalid.")
    if state_event not in ("close", "reopen", "merge"):
        _log("error", "VALIDATION_ERROR", "state_event is invalid")
        return _err("VALIDATION_ERROR", "state_event must be one of: close, reopen, merge.")
    if state_event == "merge":
        if not isinstance(merged_by_user_id, str) or not re.match(r"^gl_user_[0-9A-HJKMNP-TV-Z]{10,}$", merged_by_user_id):
            _log("error", "VALIDATION_ERROR", "merged_by_user_id is invalid")
            return _err("VALIDATION_ERROR", "merged_by_user_id is required and must be a valid user id when merging.")
        if merge_commit_message is not None and not isinstance(merge_commit_message, str):
            _log("error", "VALIDATION_ERROR", "merge_commit_message is invalid")
            return _err("VALIDATION_ERROR", "merge_commit_message must be a string.")

    # Authenticate access_token ambiently: match any stored token in access_tokens.json if present,
    # otherwise allow if the store has no token collection (offline simplified)
    token_rows = _load("access_tokens.json")
    authed_user_id = None
    if isinstance(token_rows, list) and token_rows:
        for r in token_rows:
            if isinstance(r, dict) and (r.get("token") == access_token or r.get("id") == access_token):
                if r.get("status", "active") == "active":
                    authed_user_id = r.get("user_id") or r.get("owner_user_id")
                    break
        if not authed_user_id:
            _log("error", "UNAUTHORIZED", "invalid access_token")
            return _err("UNAUTHORIZED", "access_token is invalid.")
    else:
        authed_user_id = None  # no token DB => treat as already authenticated

    mrs = _load("merge_requests.json")
    mr = next((x for x in mrs if isinstance(x, dict) and x.get("id") == merge_request_id and x.get("status", "active") != "deleted"), None)
    if not mr:
        _log("error", "NOT_FOUND", "merge request not found")
        return _err("NOT_FOUND", "merge request not found.")

    # Basic authorization: if token resolved to a user, require they're the author (simplified)
    if authed_user_id is not None and authed_user_id != mr.get("author_user_id"):
        _log("error", "UNAUTHORIZED", "not allowed to update merge request")
        return _err("UNAUTHORIZED", "Not allowed to update this merge request.")

    current_state = mr.get("state")
    # transitions: opened -> merged/closed; closed -> opened; merged -> none
    def _allowed(next_state):
        return (
            (current_state == "opened" and next_state in ("closed", "merged")) or
            (current_state == "closed" and next_state == "opened")
        )

    if state_event == "close":
        if not _allowed("closed"):
            _log("error", "INVALID_TRANSITION", "cannot close from current state")
            return _err("INVALID_TRANSITION", f"Cannot close merge request from state '{current_state}'.")
        mr["state"] = "closed"
        mr["updated_at"] = now
        _save("merge_requests.json", mrs)
        _log("success")
        return {"merge_request": mr}

    if state_event == "reopen":
        if not _allowed("opened"):
            _log("error", "INVALID_TRANSITION", "cannot reopen from current state")
            return _err("INVALID_TRANSITION", f"Cannot reopen merge request from state '{current_state}'.")
        mr["state"] = "opened"
        mr["updated_at"] = now
        _save("merge_requests.json", mrs)
        _log("success")
        return {"merge_request": mr}

    # merge
    if not _allowed("merged"):
        _log("error", "INVALID_TRANSITION", "cannot merge from current state")
        return _err("INVALID_TRANSITION", f"Cannot merge merge request from state '{current_state}'.")
    if mr.get("merge_status") != "can_be_merged":
        _log("error", "CONFLICT", "merge_status does not allow merge")
        return _err("CONFLICT", "Merge request cannot be merged due to merge_status.")
    mr["state"] = "merged"
    mr["updated_at"] = now
    mr["merged_by_user_id"] = merged_by_user_id
    if merge_commit_message is not None:
        mr["merge_commit_message"] = merge_commit_message
    _save("merge_requests.json", mrs)
    _log("success")
    return {"merge_request": mr}
